create table if not exists public.mingle_stories (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,media_path text not null,media_type text not null,caption text not null default '',overlay jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),expires_at timestamptz not null default (now()+interval '24 hours'));create index if not exists mingle_stories_active on public.mingle_stories(expires_at);alter table public.mingle_stories enable row level security;create policy "Read active stories" on public.mingle_stories for select to authenticated using(expires_at>now() or user_id=auth.uid());create policy "Create own stories" on public.mingle_stories for insert to authenticated with check(user_id=auth.uid());create policy "Delete own stories" on public.mingle_stories for delete to authenticated using(user_id=auth.uid());create table if not exists public.mingle_story_views(story_id uuid not null references public.mingle_stories(id) on delete cascade,viewer_id uuid not null references auth.users(id) on delete cascade,viewed_at timestamptz not null default now(),primary key(story_id,viewer_id));alter table public.mingle_story_views enable row level security;create policy "View own story viewers" on public.mingle_story_views for select to authenticated using(viewer_id=auth.uid() or exists(select 1 from public.mingle_stories s where s.id=story_id and s.user_id=auth.uid()));create policy "Record own views" on public.mingle_story_views for insert to authenticated with check(viewer_id=auth.uid());insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('mingle-stories','mingle-stories',true,52428800,array['image/jpeg','image/png','image/webp','video/mp4','video/webm']) on conflict(id) do nothing;create policy "Read story media" on storage.objects for select to authenticated using(bucket_id='mingle-stories');create policy "Upload story media" on storage.objects for insert to authenticated with check(bucket_id='mingle-stories' and (storage.foldername(name))[1]=auth.uid()::text);create policy "Delete story media" on storage.objects for delete to authenticated using(bucket_id='mingle-stories' and (storage.foldername(name))[1]=auth.uid()::text);